export const DMC_STUDENT_BY_CODE = new Map<string, DmcStudentMaster>(
  DMC_STUDENTS_MASTER.map(s => [s.code, s])
);

export const DMC_STUDENT_BY_NAME = new Map<string, DmcStudentMaster>(
  DMC_STUDENTS_MASTER.map(s => [s.name.replace(/\s+/g, ' ').trim(), s])
);

export function findDmcStudent(codeOrId?: string, name?: string): DmcStudentMaster | undefined {
  if (codeOrId) {
    const cleanCode = codeOrId.replace(/^student_/, '').trim();
    const byCode = DMC_STUDENT_BY_CODE.get(cleanCode);
    if (byCode) return byCode;
  }
  if (name) {
    const cleanName = name.replace(/\s+/g, ' ').trim();
    const byName = DMC_STUDENT_BY_NAME.get(cleanName);
    if (byName) return byName;
  }
  return undefined;
}

export function getDmcClassRosters() {
  return DMC_CLASS_METADATA.map(meta => ({
    classId: meta.roomId,
    acadId: meta.acadId,
    shortClass: meta.shortClass,
    label: meta.label,
    fullClassName: meta.fullClassName,
    levelGroup: meta.levelGroup,
    homeroomTeacher: meta.homeroomTeacher,
    students: DMC_STUDENTS_MASTER.filter(s => s.roomId === meta.roomId),
  }));
}
